-- Snowflake-specific: VARIANT paths, FLATTEN, IFF, TRY_*, ILIKE ANY, SAMPLE, time travel
SELECT payload:user.id::number AS user_id, payload:user.name::string AS name FROM raw_events;
SELECT payload:items[0].sku::string AS first_sku, payload:items[1]:qty::int AS second_qty FROM raw_orders;
SELECT src:"customer id"::string AS cid, src['order']['total']::float AS total FROM raw_json;
SELECT GET_PATH(payload, 'a.b.c') AS deep, payload:a.b.c AS deep2 FROM t;
SELECT e.payload:id::string AS id, f.value:sku::string AS sku, f.index AS idx FROM raw_orders e, LATERAL FLATTEN(input => e.payload:items) f;
SELECT o.id, f.value:sku::string AS sku, f.value:qty::number AS qty FROM orders o, LATERAL FLATTEN(input => o.items, outer => TRUE) f;
SELECT f.key, f.value FROM TABLE(FLATTEN(input => PARSE_JSON('{"a":1,"b":2}'))) f;
SELECT t.id, f.value::string AS tag FROM tbl t, TABLE(FLATTEN(t.tags)) f;
SELECT id, f.path, f.value FROM events, LATERAL FLATTEN(input => payload, recursive => TRUE) f WHERE f.key = 'email';
SELECT IFF(score >= 60, 'pass', 'fail') AS result, ZEROIFNULL(bonus) AS bonus, NULLIFZERO(qty) AS qty FROM exam;
SELECT TRY_TO_NUMBER(s) AS n, TRY_TO_DATE(d, 'YYYY-MM-DD') AS dt, TRY_TO_TIMESTAMP(ts) AS t, TRY_TO_BOOLEAN(b) AS bl, TRY_PARSE_JSON(j) AS js FROM raw_strings;
SELECT TO_VARIANT(x), TO_VARCHAR(y), TO_TIMESTAMP_NTZ(z), TO_DECIMAL(q, 10, 2) FROM t;
SELECT * FROM products WHERE name ILIKE ANY ('%shoe%', '%boot%');
SELECT * FROM products WHERE name LIKE ANY ('a%', 'b%') AND sku NOT ILIKE ALL ('x%', 'y%');
SELECT * FROM users WHERE email RLIKE '.*@example\\.com';
SELECT * FROM users WHERE REGEXP_LIKE(email, '^[a-z]+@example\\.com$', 'i');
SELECT * FROM orders AT (TIMESTAMP => '2024-06-01 12:00:00'::timestamp_tz);
SELECT * FROM orders AT (OFFSET => -60*5);
SELECT * FROM orders BEFORE (STATEMENT => '8e5d0ca9-005e-44e6-b858-a8f5b37c5726');
SELECT * FROM orders AT (TIMESTAMP => DATEADD(hour, -1, CURRENT_TIMESTAMP())) o JOIN customers c ON c.id = o.customer_id;
SELECT * FROM big_table SAMPLE (10);
SELECT * FROM big_table TABLESAMPLE BERNOULLI (5);
SELECT * FROM big_table SAMPLE SYSTEM (1) SEED (42);
SELECT * FROM big_table SAMPLE (1000 ROWS);
SELECT $1, $2, $3 FROM @my_stage/data.csv (FILE_FORMAT => 'my_csv');
SELECT t.$1 AS id, t.$2 AS name FROM @my_stage/users/ (FILE_FORMAT => 'my_csv', PATTERN => '.*[.]csv') t;
SELECT $1:id::number AS id, $1:name::string AS name FROM @json_stage (FILE_FORMAT => 'my_json');
SELECT METADATA$FILENAME, METADATA$FILE_ROW_NUMBER, $1 FROM @my_stage;
SELECT * FROM TABLE(INFORMATION_SCHEMA.QUERY_HISTORY(RESULT_LIMIT => 100));
SELECT * FROM TABLE(RESULT_SCAN(LAST_QUERY_ID()));
SELECT * FROM TABLE(GENERATOR(ROWCOUNT => 100));
SELECT SEQ4() AS n, UNIFORM(1, 100, RANDOM()) AS r FROM TABLE(GENERATOR(ROWCOUNT => 10));
SELECT OBJECT_CONSTRUCT('a', 1, 'b', 'two') AS o, ARRAY_CONSTRUCT(1, 2, 3) AS a, OBJECT_INSERT(OBJECT_CONSTRUCT(), 'k', 'v') AS o2;
SELECT ARRAY_SIZE(payload:items) AS n, ARRAY_CONTAINS('x'::variant, tags) AS has_x, ARRAY_TO_STRING(tags, ',') AS s FROM t;
SELECT OBJECT_KEYS(payload) AS ks, TYPEOF(payload:id) AS ty, IS_NULL_VALUE(payload:x) AS nv FROM t;
SELECT CURRENT_ACCOUNT(), CURRENT_REGION(), CURRENT_WAREHOUSE(), CURRENT_ROLE(), CURRENT_DATABASE(), CURRENT_SCHEMA();
SELECT DATEADD(day, 7, CURRENT_DATE()), DATEDIFF(day, '2024-01-01', '2024-02-01'), LAST_DAY(CURRENT_DATE(), 'month'), DATE_FROM_PARTS(2024, 2, 29);
SELECT CONVERT_TIMEZONE('UTC', 'America/Los_Angeles', ts) AS la_time FROM events;
SELECT ts::date AS d, ts::time AS t, '123'::number(10,2) AS n, x::variant AS v FROM t;
SELECT EDITDISTANCE(a, b), JAROWINKLER_SIMILARITY(a, b), SOUNDEX(a), SPLIT_PART(email, '@', 2), STRTOK(path, '/', 2) FROM t;
SELECT HASH(a, b), MD5(a), SHA2(a, 256), BITAND(a, b), BOOLAND_AGG(flag), BITOR_AGG(mask) FROM t GROUP BY g;
SELECT * FROM t WHERE col IN (SELECT value FROM TABLE(FLATTEN(input => SPLIT('a,b,c', ','))));
SELECT $$multi
line string$$ AS s;
SELECT 'it''s' AS q, 1e3 AS sci, .5 AS frac;
SELECT * FROM "My Table" WHERE "Mixed Case Col" = 1;
SELECT a.* EXCLUDE (secret), b.* RENAME (id AS b_id) FROM a JOIN b ON a.id = b.a_id;
SELECT * EXCLUDE (ssn, dob) FROM customers;
SELECT * ILIKE '%name%' FROM customers;
SELECT * REPLACE (UPPER(name) AS name) FROM customers;
SELECT {'a': 1, 'b': 'two'} AS obj, [1, 2, 3] AS arr;
SELECT * FROM t1 ASOF JOIN t2 MATCH_CONDITION (t1.ts >= t2.ts) ON t1.sym = t2.sym;
